query inventory($id : String!){
  data: inventory(where: {id: {_eq: $id}}) {
    edges {
      node {
        id
        number
        productStrategyProcessId
        productStrategyProcess{
        productStrategy{
      productId
    }
    }
        locationId
      }
    }
  }
}

query setupBom($workcenterId: String!, $componentProductId: String!) {
  data: productionSetupBOM(where: {productionSetup: {workcenterId: {_eq: $workcenterId}},
    componentProductId:{
      _eq:$componentProductId
    }
  },


  ) {
    edges {
      node {
        id
        productionSetupId
        componentProductStrategyProcessId
        productionSetup {
          id
          workcenterId
          workcenterPositionId
        }
      }
    }
  }
}

query productionSetupMaterial($inventoryId : String!){
  data: productionSetupMaterial(where: {inventoryId: {_eq: $inventoryId}}) {
    edges {
      node {
        id
        inventoryId
      }
    }
  }
}

